const slides=[...document.querySelectorAll('.slide')];let current=0;
const tests=[
 {name:'1. Ticket claro · Gas Chacabuco',status:'CONFIRMADO',class:'confirmed',title:'Registro preparado para revisión',summary:'El comprobante muestra datos críticos suficientes.',property:'Chacabuco',concept:'Gas',amount:'$ 9.535,67 → 9535.67',row:'gas chacabuco',evidence:'Servicio, propiedad y monto legibles'},
 {name:'2. PDF · Tres conceptos',status:'REQUIERE ACLARACIÓN',class:'clarify',title:'Separar antes de cargar',summary:'Hay varios conceptos; no existe un único monto contable.',property:'Urquiza',concept:'Alquiler, Expensas y Luz',amount:'$ 450.000 / $ 38.500 / $ 12.900',row:'Tres filas propuestas',evidence:'Revisar que cada importe corresponda al período'},
 {name:'3. Transferencia · Motivo “Varios”',status:'REQUIERE ACLARACIÓN',class:'clarify',title:'El contexto no alcanza',summary:'La regla mejorada impide inferir un servicio a partir de “Varios”.',property:'No confirmada',concept:'No informado',amount:'$ 25.000',row:'Sin fila propuesta',evidence:'Acción: pedir servicio y propiedad al remitente'},
 {name:'4. Imagen recortada',status:'REQUIERE ACLARACIÓN',class:'clarify',title:'No hay monto verificable',summary:'Se reconoce el servicio, pero el total está cortado.',property:'Pendiente de confirmar',concept:'Visible en imagen',amount:'No legible',row:'Sin fila propuesta',evidence:'Acción: solicitar imagen completa'},
 {name:'5. Ticket no pertinente',status:'FUERA DE ALCANCE',class:'outside',title:'Archivo descartado',summary:'No corresponde a un servicio de la propiedad indicada.',property:'No aplicable',concept:'Ticket de supermercado',amount:'No procesar',row:'Sin fila propuesta',evidence:'Acción: informar discrepancia y conservar trazabilidad'}
];
const select=document.querySelector('#caseSelect');tests.forEach((t,i)=>select.add(new Option(t.name,i)));
function show(i){current=(i+slides.length)%slides.length;slides.forEach((s,n)=>s.classList.toggle('active',n===current));document.querySelector('#counter').textContent=`${current+1} / ${slides.length}`;document.querySelector('#progressFill').style.width=`${((current+1)/slides.length)*100}%`;history.replaceState(null,'',`#${slides[current].id||slides[current].dataset.title}`)}
function next(){show(current+1)}function prev(){show(current-1)}
document.querySelector('#nextBtn').onclick=next;document.querySelector('#prevBtn').onclick=prev;document.querySelectorAll('[data-next]').forEach(b=>b.onclick=next);document.querySelector('#restartBtn').onclick=()=>show(0);
document.addEventListener('keydown',e=>{if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();next()}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();prev()}if(e.key==='f'||e.key==='F')toggleFull()});
function toggleFull(){if(!document.fullscreenElement)document.documentElement.requestFullscreen?.();else document.exitFullscreen?.()}document.querySelector('#fullscreenBtn').onclick=toggleFull;
document.querySelector('#runBtn').onclick=()=>{const t=tests[select.value];document.querySelector('#result').innerHTML=`<div class="result-card"><span class="status ${t.class}">${t.status}</span><h3>${t.title}</h3><p>${t.summary}</p><div class="result-grid"><div><small>PROPIEDAD</small><b>${t.property}</b></div><div><small>CONCEPTO</small><b>${t.concept}</b></div><div><small>MONTO</small><b>${t.amount}</b></div><div><small>FILA PROPUESTA</small><b>${t.row}</b></div><div style="grid-column:1/-1"><small>EVIDENCIA / ACCIÓN</small><b>${t.evidence}</b></div></div></div>`};show(0);
